/**
 * tenant-plan — self-service plan change for a tenant's base license
 * (design doc 3.8; implementation plan W17).
 *
 *   GET  /tenants/{id}/plan          current cadence, seats, status, paid-through
 *                                    date and any pending (deferred) change
 *   POST /tenants/{id}/plan          { billingCadence, userCount?, preview }
 *                                    preview:true -> the platform's preview, unchanged
 *                                    in meaning; preview:false -> apply, returns the
 *                                    updated license
 *   POST /tenants/{id}/plan/cancel   cancel the pending change
 *
 * Authorization: the admin-pool JWT authorizer, then the caller must be SA
 * or TA_<id> of this tenant (3.8). SPA is not in the 3.8 list and is
 * refused. The tenant's `billingCustomerId` / `licenseId` come from its
 * TENANT# record (written by the orchestrator at 3.4 j); a tenant without
 * them (admin-created, Phase 2) gets 409 `no_billing_account`.
 *
 * The browser never sees the billing key or the license key, and no string
 * from a billing reply is forwarded (W9): responses carry numbers, booleans,
 * enum-checked cadence/status values, ISO dates and our own text only.
 *
 * Placement: the shared VPC behind the NAT EIP (billing key is IP-pinned, D5).
 *
 * Env: AMFATENANT_TABLE, BILLING_BASE_URL, BILLING_INSTALL_URL,
 * BILLING_SECRET_ID, SIGNUP_MAX_USER_COUNT.
 */

import { dynamodbClient, QueryCommand, TABLE } from "../shared/signup/state.mjs";
import { getLicense, changePlan, cancelPlanChange } from "../shared/billing/client.mjs";
import { BillingError } from "../shared/billing/errors.mjs";

export const MAX_USER_COUNT = Number(process.env.SIGNUP_MAX_USER_COUNT) || 50_000;
export const ROUTE_BUDGET_MS = Number(process.env.PLAN_ROUTE_BUDGET_MS) || 27_000;
const MAX_BODY_BYTES = 16 * 1024;
const DDB_CALL_MS = 3_000;
const CADENCES = new Set(["monthly", "yearly"]);
/** Platform enum (1.5); anything else is reported as null, never echoed. */
const LICENSE_STATUSES = new Set(["pending", "active", "suspended", "revoked", "expired", "lapsed"]);
const ISO_DATE = /^\d{4}-\d{2}-\d{2}(T[\d:.]+Z?)?$/;
const TENANT_ID = /^[a-z0-9][a-z0-9-]{0,62}$/;

const log = (level, message, extra = {}) =>
  console.log(JSON.stringify({ timestamp: new Date().toISOString(), level, service: "tenant-plan", message, ...extra }));

const respond = (statusCode, body) => ({
  statusCode,
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify(body),
});

class HttpError extends Error {
  constructor(statusCode, body) { super(body.errorCode || body.message); this.statusCode = statusCode; this.body = body; }
}

// ---------------------------------------------------------------------------
// Authorization (3.8: SA or TA of this tenant)
// ---------------------------------------------------------------------------

/** cognito:groups from the JWT authorizer, as an array. */
export function groupsOf(event) {
  let groups = event.requestContext?.authorizer?.jwt?.claims?.["cognito:groups"] ?? [];
  if (typeof groups === "string") groups = groups.replace(/^\[|\]$/g, "").split(",").map((g) => g.trim()).filter(Boolean);
  return Array.isArray(groups) ? groups : [];
}

/** True for SA, or TA_<tenantId>. SPA is deliberately not included (3.8). */
export function mayManagePlan(groups, tenantId) {
  return groups.includes("SA") || groups.includes(`TA_${tenantId}`);
}

function tenantIdOf(event) {
  const id = event.pathParameters?.id;
  if (typeof id !== "string" || !TENANT_ID.test(id)) throw new HttpError(400, { errorCode: "validation_error", field: "id", message: "id: invalid tenant id" });
  return id;
}

async function authorize(event) {
  const tenantId = tenantIdOf(event);
  const claims = event.requestContext?.authorizer?.jwt?.claims;
  if (!claims) throw new HttpError(500, { errorCode: "misconfigured", message: "missing JWT claims" });
  // Role check BEFORE the record read: a caller outside the tenant learns nothing, not even existence.
  if (!mayManagePlan(groupsOf(event), tenantId)) throw new HttpError(403, { errorCode: "forbidden" });
  return tenantId;
}

// ---------------------------------------------------------------------------
// TENANT# record (owned by provision-tenant; read-only here)
// ---------------------------------------------------------------------------

async function loadTenant(tenantId) {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), DDB_CALL_MS);
  try {
    const res = await dynamodbClient.send(
      new QueryCommand({
        TableName: TABLE,
        KeyConditionExpression: "id = :id AND begins_with(sk, :p)",
        ExpressionAttributeValues: { ":id": { S: `TENANT#${tenantId}` }, ":p": { S: "TENANT#" } },
        Limit: 1,
        // The orchestrator writes the billing ids at 3.4 j moments before the
        // user can first open this page; an eventually consistent read could
        // answer 409 for a tenant that is complete (codex W17 round 2 P2).
        ConsistentRead: true,
      }),
      { abortSignal: ctrl.signal },
    );
    const item = res.Items?.[0];
    if (!item) throw new HttpError(404, { errorCode: "tenant_not_found" });
    const num = (k) => { const v = item[k]?.N ?? item[k]?.S; const n = Number(v); return v !== undefined && Number.isInteger(n) && n > 0 ? n : undefined; };
    const billingCustomerId = num("billingCustomerId");
    const licenseId = num("licenseId");
    if (!billingCustomerId || !licenseId) {
      // Admin-created tenants have no billing customer until Phase 2 (3.8 "Not included").
      throw new HttpError(409, { errorCode: "no_billing_account", message: "This tenant has no self-service billing plan. Contact support to change it." });
    }
    return { tenantId, billingCustomerId, licenseId };
  } finally {
    clearTimeout(timer);
  }
}

// ---------------------------------------------------------------------------
// Projections (W9: no upstream strings reach the browser)
// ---------------------------------------------------------------------------

const int = (v) => (Number.isInteger(v) && v >= 0 ? v : null);
const cadence = (v) => (CADENCES.has(v) ? v : (typeof v === "string" ? "other" : null));
const status = (v) => (LICENSE_STATUSES.has(v) ? v : null);
const date = (v) => (typeof v === "string" && ISO_DATE.test(v) ? v.slice(0, 10) : null);

/** Seats as the platform stores them: `allowed_users` on monthly, `user_count` otherwise (1.5). */
function seatsOf(license) {
  const cad = license?.billing_cadence;
  return int(cad === "monthly" ? license?.allowed_users : license?.user_count) ?? int(license?.user_count) ?? int(license?.allowed_users);
}

/** GET /v1/licenses/{id}, projected for the Plan page. */
export function projectLicense(license) {
  const pendingCadence = cadence(license?.pending_billing_cadence);
  const pendingSeats = int(license?.pending_user_count);
  const pendingDate = date(license?.pending_effective_date);
  return {
    licenseId: int(license?.id),
    status: status(license?.status),
    billingCadence: cadence(license?.billing_cadence),
    seats: seatsOf(license),
    paidThroughDate: date(license?.paid_through_date),
    pendingChange: pendingCadence || pendingSeats !== null || pendingDate
      ? { billingCadence: pendingCadence, seats: pendingSeats, effectiveDate: pendingDate }
      : null,
  };
}

/**
 * change-plan preview, projected. The platform's preview shape is pinned on
 * dev (W12, like the W10 tiers): we pass through the cents and date fields
 * we know of, each individually validated, and an `otherFieldCount` so a
 * reviewer can see when the platform sent more than we display.
 */
export function projectPreview(selection, preview) {
  const cents = (k) => (typeof preview?.[k] === "number" && preview[k] >= 0 ? preview[k] : null);
  const known = ["total_due_cents", "amount_due_cents", "prorated_cents", "effective_date", "billing_cadence", "user_count", "allowed_users", "warnings", "fees"];
  // The figure to show: total (with fees, 1.5 "show that one") first, then
  // the alternatives. `chargeKnown` false means the platform sent none of
  // them; the page must then refuse to apply a charged change (Q34a).
  const chargeCents = cents("total_due_cents") ?? cents("amount_due_cents") ?? cents("prorated_cents");
  return {
    billingCadence: selection.billingCadence,
    userCount: selection.userCount ?? null,
    totalDueCents: cents("total_due_cents"),
    amountDueCents: cents("amount_due_cents"),
    proratedCents: cents("prorated_cents"),
    chargeCents,
    chargeKnown: chargeCents !== null,
    chargedNow: chargeCents !== null && chargeCents > 0,
    effectiveDate: date(preview?.effective_date),
    warningCount: Array.isArray(preview?.warnings) ? preview.warnings.length : 0,
    otherFieldCount: preview && typeof preview === "object" ? Object.keys(preview).filter((k) => !known.includes(k)).length : 0,
  };
}

// ---------------------------------------------------------------------------
// Input
// ---------------------------------------------------------------------------

function parseBody(event) {
  const raw = event.isBase64Encoded ? Buffer.from(event.body || "", "base64").toString("utf8") : (event.body || "");
  if (Buffer.byteLength(raw, "utf8") > MAX_BODY_BYTES) throw new HttpError(413, { errorCode: "body_too_large" });
  try { return raw ? JSON.parse(raw) : {}; } catch { throw new HttpError(400, { errorCode: "validation_error", message: "body: invalid JSON" }); }
}

/**
 * { billingCadence, userCount?, preview } -> selection. Yearly needs a seat
 * count (3.8: never rely on the platform's peak default); monthly must not
 * carry one (the platform refuses it). preview is a required boolean so a
 * client cannot apply by accident through a missing field.
 */
export function validateChange(body) {
  const bad = (field, message) => new HttpError(400, { errorCode: "validation_error", field, message: `${field}: ${message}` });
  if (!body || typeof body !== "object" || Array.isArray(body)) throw bad("body", "must be an object");
  if (!CADENCES.has(body.billingCadence)) throw bad("billingCadence", "must be monthly or yearly");
  if (typeof body.preview !== "boolean") throw bad("preview", "must be true or false");
  const uc = body.userCount;
  if (body.billingCadence === "yearly") {
    if (!Number.isInteger(uc) || uc < 1 || uc > MAX_USER_COUNT) throw bad("userCount", `must be an integer from 1 to ${MAX_USER_COUNT} for a yearly plan`);
    return { billingCadence: "yearly", userCount: uc, preview: body.preview };
  }
  if (uc !== undefined && uc !== null) throw bad("userCount", "not accepted for a monthly plan (monthly bills registered users)");
  return { billingCadence: "monthly", userCount: undefined, preview: body.preview };
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// Every route carries one absolute deadline (API Gateway cuts the
// connection at 30 s): the billing client clamps its attempts to it and
// never starts an apply it could not report back (codex W17 round 1 P1).
const routeDeadline = () => Date.now() + ROUTE_BUDGET_MS;

async function getPlan(event) {
  const deadlineAt = routeDeadline();
  const tenantId = await authorize(event);
  const tenant = await loadTenant(tenantId);
  return respond(200, { tenantId, ...projectLicense(await getLicense(tenant.licenseId, { deadlineAt })) });
}

async function postPlan(event) {
  const deadlineAt = routeDeadline();
  const tenantId = await authorize(event);
  const selection = validateChange(parseBody(event));
  const tenant = await loadTenant(tenantId);
  const result = await changePlan(tenant.licenseId, { billingCadence: selection.billingCadence, seats: selection.userCount, preview: selection.preview, deadlineAt });
  if (selection.preview) return respond(200, { tenantId, preview: true, ...projectPreview(selection, result) });
  log("INFO", "plan change applied", { tenantId, licenseId: tenant.licenseId, billingCadence: selection.billingCadence, userCount: selection.userCount ?? null, sub: event.requestContext?.authorizer?.jwt?.claims?.sub, requestId: event.requestContext?.requestId });
  // The write's own response shape is unverified (Q40); the page state comes
  // from a fresh GET of the license (codex W17 round 6 P2). If that read fails
  // the caller gets the billing error and re-reads itself; the write stands.
  return respond(200, { tenantId, preview: false, ...projectLicense(await getLicense(tenant.licenseId, { deadlineAt })) });
}

async function postCancel(event) {
  const deadlineAt = routeDeadline();
  const tenantId = await authorize(event);
  const tenant = await loadTenant(tenantId);
  await cancelPlanChange(tenant.licenseId, { deadlineAt });
  log("INFO", "pending plan change cancelled", { tenantId, licenseId: tenant.licenseId, sub: event.requestContext?.authorizer?.jwt?.claims?.sub, requestId: event.requestContext?.requestId });
  return respond(200, { tenantId, ...projectLicense(await getLicense(tenant.licenseId, { deadlineAt })) });
}

export const handler = async (event) => {
  const path = event.rawPath || event.requestContext?.http?.path || "";
  const method = event.requestContext?.http?.method || "";
  const requestId = event.requestContext?.requestId;
  try {
    if (method === "GET" && /\/tenants\/[^/]+\/plan$/.test(path)) return await getPlan(event);
    if (method === "POST" && /\/tenants\/[^/]+\/plan$/.test(path)) return await postPlan(event);
    if (method === "POST" && /\/tenants\/[^/]+\/plan\/cancel$/.test(path)) return await postCancel(event);
    return respond(404, { errorCode: "not_found" });
  } catch (err) {
    if (err instanceof HttpError) return respond(err.statusCode, err.body);
    if (err instanceof BillingError) {
      // D3: stable code + our own text to the caller; the platform's detail
      // stays HERE, bounded, so support can tell the refusals apart (one
      // code covers them all). A change-plan request carries no secret
      // (cadence, count, flags), so the detail cannot echo one.
      log(err.status >= 500 ? "ERROR" : "WARN", "billing refused", { path, code: err.code, httpStatus: err.extra?.httpStatus, platformCode: err.extra?.platformCode, detail: typeof err.extra?.detail === "string" ? err.extra.detail.slice(0, 300) : undefined, requestId });
      return respond(err.status, { errorCode: `billing_${err.code}`, message: err.userMessage });
    }
    log("ERROR", "unhandled", { path, cause: err?.name, code: err?.code, requestId });
    return respond(500, { errorCode: "internal_error" });
  }
};
